//! `tokens`, `accounts` and `providers` subcommands.
//!
//! Split from `cli.rs` to keep that file within the repository's 1000-line
//! limit.

#[derive(Debug, Subcommand)]
pub enum TokenOp {
    /// Issue a new token and print it to stdout.
    ///
    /// `create` and `add` are accepted too: creating something was `tokens
    /// issue`, `providers add` and `clients setup` — three verbs for one idea
    /// (issue #314).
    #[command(alias = "create", alias = "add")]
    Issue {
        #[arg(long, default_value_t = 24)]
        ttl_hours: i64,
        #[arg(long, default_value = "")]
        label: String,
        #[arg(long)]
        account: Option<String>,
        /// Cap on the number of upstream requests this token may make.
        /// Omit for an unlimited token.
        #[arg(long)]
        max_requests: Option<u64>,
        /// Cap on actual input plus output tokens reported by upstreams.
        /// Omit for unlimited spend.
        #[arg(long)]
        max_tokens: Option<u64>,
        /// Maximum requests admitted per one-minute window.
        #[arg(long)]
        rate_limit_per_minute: Option<u64>,
        /// Issue an administrative token (`scope: admin`) that unlocks the
        /// admin endpoints instead of only the inference proxy.
        #[arg(long)]
        admin: bool,
        /// Restrict this token's GitHub proxy access to `owner/repo`. Repeat
        /// for several repositories; omit for unrestricted access, which is
        /// the default and what every existing token keeps.
        #[arg(long = "github-repo", value_name = "OWNER/REPO")]
        github_repo: Vec<String>,
        /// Exact model id this token may request. Repeat for several; omit
        /// for the established unpinned behaviour.
        #[arg(long = "allowed-model", value_name = "MODEL")]
        allowed_model: Vec<String>,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Replace a token, preserving its controls, and revoke the old token.
    Rotate {
        /// Subject id (`sub`) of the token being replaced.
        id: String,
        #[arg(long, default_value_t = 24)]
        ttl_hours: i64,
        #[arg(long, default_value = "")]
        label: String,
        /// Replacement request cap; omitted keeps the existing one.
        #[arg(long)]
        max_requests: Option<u64>,
        /// Replacement token spend cap; omitted keeps the existing one.
        #[arg(long)]
        max_tokens: Option<u64>,
        /// Replacement per-minute request rate; omitted keeps the existing one.
        #[arg(long)]
        rate_limit_per_minute: Option<u64>,
        /// Replacement account pin; omitted keeps the existing one.
        #[arg(long)]
        account: Option<String>,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// List all known tokens.
    List {
        /// Emit JSON instead of the table.
        ///
        /// Every `list` printed a table unconditionally and every `show`
        /// printed JSON unconditionally, so neither could be asked for the
        /// other form — and `--json` existed on two subcommands only
        /// (issue #314).
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Revoke a token by id.
    ///
    /// `remove` and `delete` are accepted too: destroying something was
    /// `providers remove`, `clients remove`, `server remove`, `tokens revoke`
    /// and `tokens expire` (issue #314).
    #[command(alias = "remove", alias = "delete")]
    Revoke {
        id: String,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Revoke a token by id — an alias of `revoke`, kept for scripts.
    ///
    /// Both arms have always collapsed into the same call and printed
    /// `revoked <ID>`, while the help promised a distinct operation
    /// (issue #314). It is documented as the alias it is.
    Expire {
        id: String,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Show metadata for one token.
    Show {
        id: String,
        /// Accepted for symmetry with `list`: `show` already emits JSON, so
        /// this changes nothing (issue #314). A script should not have to know
        /// which verb of a family takes the flag.
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Mint a replacement administrative token from the local token store.
    ///
    /// The recovery path for a lost admin token. Every other verb in this
    /// family authenticates with the admin credential, so losing it left an
    /// operator who still owned the store, the volume and the machine with no
    /// way back in — and the standing advice was to destroy the deployment and
    /// discard every issued client token and the whole request log to recover
    /// from having misplaced one string (issue #573).
    ///
    /// The admin token is a signed JWT and the store keeps only its metadata,
    /// so the lost value cannot be re-read. What *can* be done is to sign a new
    /// one: this reads `TOKEN_SECRET` and the store directly, exactly as the
    /// server does at boot, and mints an admin token the running deployment
    /// already accepts — no restart, and issued client tokens, provider
    /// configuration and the request log are untouched.
    ///
    /// Gated on local ownership rather than on a credential. Reading the store
    /// is already equivalent to full control of the deployment, so this grants
    /// no authority its caller lacks; it only makes existing authority usable.
    /// For that reason it is never available over HTTP: with another router
    /// selected it refuses and names the machine it would have acted on, the
    /// same boundary `auth import` and `auth clear` draw.
    #[command(name = "recover-admin")]
    RecoverAdmin {
        /// Revoke every other admin token once the replacement is minted.
        ///
        /// For a credential believed to be in someone else's hands: recovery
        /// alone adds an administrator without removing the lost one.
        #[arg(long)]
        revoke_others: bool,
        #[arg(long, default_value_t = 24 * 365)]
        ttl_hours: i64,
        #[arg(long, default_value = "recovered-admin")]
        label: String,
        /// Emit the stable JSON envelope instead of human-readable output.
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Copy token records from another data root, deployment root, deploy
    /// checkpoint or token file into this store (issue #644).
    ///
    /// A rollback or data-root switch can leave a live token whose signature
    /// verifies but whose durable record is absent, so the router answers 401
    /// to a session that did nothing wrong. This brings the exact record back
    /// — same id, binding, scope, expiry, lease, budgets, usage and model
    /// policy — without rotating anything or touching the signing secret.
    ///
    /// By default only missing records are added and every existing record is
    /// left exactly as it is; records that differ are reported field by field.
    /// `--replace` overwrites those too, after saving the current records to
    /// `token-import-backups/`, and even then never revives a revoked record
    /// or lowers recorded usage. Local only: it needs the store itself.
    Import {
        /// Source: a data directory (`tokens.lino`/`tokens.bin`), a deployment
        /// root with `data/`, a checkpoint with `tokens.json`, or one file.
        #[arg(long, value_name = "PATH")]
        from: PathBuf,
        /// Import only this token id (repeatable).
        #[arg(long = "id", value_name = "ID")]
        ids: Vec<String>,
        /// Overwrite records that differ, after backing up the current ones.
        #[arg(long)]
        replace: bool,
        /// Report what would change without writing anything.
        #[arg(long)]
        dry_run: bool,
        /// Emit the report as JSON.
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
}

#[derive(Debug, Subcommand)]
pub enum AccountOp {
    /// List configured accounts and their health.
    List {
        /// Emit JSON instead of the table (issue #314).
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Take a pooled account out of rotation (issue #677).
    ///
    /// Calls `POST /api/management/accounts/{name}/pause` on the selected
    /// router. Locally (`--local`, or no selection) the pause is written to
    /// the data directory, where the router reads it when it starts.
    Pause {
        /// Account name, as `accounts list` prints it.
        name: String,
        /// Why the account is paused; shown by `accounts list --json`.
        #[arg(long)]
        reason: Option<String>,
        /// When the pause lifts on its own: Unix seconds, an RFC 3339 time,
        /// or a delay such as `90m`, `6h` or `2d`. Without it the pause lasts
        /// until `accounts resume`.
        #[arg(long, value_parser = super::value_parsers::parse_until)]
        until: Option<u64>,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Put a paused account back into rotation (issue #677).
    ///
    /// Lifts a manual pause or an `ACCOUNT_PAUSE_AT_PERCENT` one, through
    /// `POST /api/management/accounts/{name}/resume` on the selected router.
    Resume {
        /// Account name, as `accounts list` prints it.
        name: String,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Show or replace an account's persisted routing policy.
    Policy {
        /// Account name from `accounts list`.
        name: String,
        /// JSON file containing the complete replacement policy. Omit to show it.
        #[arg(long)]
        file: Option<std::path::PathBuf>,
        #[command(flatten)]
        target: AuthTarget,
    },
}

#[derive(Debug, Subcommand)]
// Keeping `AuthTarget` flattened preserves clap's public flag layout. Boxing
// only the largest variant would leak an implementation detail into every
// constructor and test for a command enum created once per process.
#[allow(clippy::large_enum_variant)]
pub enum ProviderOp {
    /// List configured upstream providers.
    List {
        /// Emit JSON instead of the table (issue #314).
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Add or replace an API provider or policy-gated credential class.
    ///
    /// `create` and `issue` are accepted too (issue #314).
    #[command(alias = "create", alias = "issue")]
    Add {
        /// Name this provider is referred to by, in routing and in `providers
        /// show`. Adding an existing name replaces that record.
        #[arg(long)]
        name: String,
        /// Wire protocol the upstream speaks.
        #[arg(long, default_value = "openai-compatible")]
        kind: String,
        /// The upstream's own base URL — not the router's. `--server` names
        /// the router; this names the machine it forwards to (issue #314).
        #[arg(long)]
        base_url: String,
        /// Single model this provider serves, for an upstream that serves one.
        #[arg(long)]
        model: Option<String>,
        /// Comma-separated models this provider serves.
        #[arg(long, value_delimiter = ',')]
        models: Vec<String>,
        /// Canonical managed clients explicitly supported by this ordinary
        /// provider adapter. Repeat or comma-separate values.
        #[arg(long = "supported-client", value_delimiter = ',')]
        supported_clients: Vec<String>,
        /// Vendor API key, stored encrypted under the deployment's
        /// `TOKEN_SECRET`.
        ///
        /// Prefer `--api-key-stdin`: a key given here is visible in shell
        /// history and in `ps` (issue #314).
        #[arg(long, hide_env_values = true, conflicts_with = "api_key_stdin")]
        api_key: Option<String>,
        /// Read the vendor API key as one line from standard input.
        ///
        /// The one secret in this tool that could travel only through argv,
        /// while every other has had a stdin form and `clients setup --help`
        /// warns against argv for exactly this reason (issue #314).
        #[arg(long, conflicts_with = "api_key")]
        api_key_stdin: bool,
        /// Environment variable the *router process* reads the key from at
        /// request time, instead of storing one.
        #[arg(long)]
        api_key_env: Option<String>,
        /// Single subscriber allowed to spend a personal Coding Plan key.
        #[arg(long)]
        subscriber_id: Option<String>,
        /// Accept the documented account risk of intermediary personal proxying.
        #[arg(long)]
        acknowledge_intermediary_risk: bool,
        /// Individually risk-accept a known tool not listed by z.ai.
        #[arg(long, value_delimiter = ',')]
        acknowledge_unsupported_client: Vec<String>,
        /// Whether this provider takes part in routing. Disabled records are
        /// kept and ignored, so one can be parked without deleting it.
        #[arg(
            long,
            default_value_t = true,
            num_args = 0..=1,
            default_missing_value = "true"
        )]
        enabled: bool,
        /// Create only when the provider name is absent; never replace it.
        #[arg(long)]
        if_absent: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Show one provider with secret material redacted.
    Show {
        name: String,
        /// Accepted for symmetry with `list`: `show` already emits JSON, so
        /// this changes nothing (issue #314). A script should not have to know
        /// which verb of a family takes the flag.
        #[arg(long)]
        json: bool,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Remove one provider.
    ///
    /// `revoke` and `delete` are accepted too (issue #314).
    #[command(alias = "revoke", alias = "delete")]
    Remove {
        name: String,
        #[command(flatten)]
        target: AuthTarget,
    },
    /// Import providers from JSON, `.lenv`, or indented Links-style config.
    Import {
        path: PathBuf,
        #[command(flatten)]
        target: AuthTarget,
    },
}
